<?php

namespace App\Services;

use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\Http;

/**
 * Thin client for SMSGate's public Cloud API (sms-gate.app — the Android
 * "SMS Gateway" app in Cloud server mode). Each TSA's own phone has its own
 * username/password (generated by the app on first connect), so every call
 * here takes them explicitly rather than reading one global credential.
 *
 * Endpoints/fields per SMSGate's own OpenAPI spec (checked 2026-10-23):
 * POST /messages {textMessage:{text}, phoneNumbers:[], ttl} → 202 enqueued;
 * GET /devices → [{id, lastSeen, ...}]. Basic auth.
 */
class SmsGateApi
{
    public const BASE_URL = 'https://api.sms-gate.app/3rdparty/v1';

    /** A phone not seen by SMSGate's cloud within this many minutes counts
     *  as offline — its text is skipped, not queued for later. */
    public const ONLINE_WITHIN_MINUTES = 10;

    /** How long SMSGate may hold the text if the phone drops right after we
     *  checked — a "we'll call you shortly" text arriving hours late is
     *  worse than none. */
    public const TTL_SECONDS = 900;

    /** true/false from the device's lastSeen, or null when the API itself
     *  couldn't be reached / credentials were rejected. */
    public function isOnline(string $username, string $password): ?bool
    {
        $res = Http::withBasicAuth($username, $password)
            ->acceptJson()->connectTimeout(4)->timeout(8)
            ->get(self::BASE_URL . '/devices');

        if (!$res->successful()) {
            return null;
        }

        $lastSeen = collect($res->json() ?? [])
            ->pluck('lastSeen')->filter()
            ->map(fn ($t) => Carbon::parse($t))
            ->max();

        return $lastSeen !== null && $lastSeen->gt(now()->subMinutes(self::ONLINE_WITHIN_MINUTES));
    }

    /** @return array{ok: bool, id: ?string, error: ?string} */
    public function send(string $username, string $password, string $phoneNumber, string $text): array
    {
        $res = Http::withBasicAuth($username, $password)
            ->acceptJson()->connectTimeout(4)->timeout(10)
            ->post(self::BASE_URL . '/messages', [
                'textMessage'  => ['text' => $text],
                'phoneNumbers' => [$phoneNumber],
                'ttl'          => self::TTL_SECONDS,
            ]);

        if ($res->status() === 202 || $res->successful()) {
            return ['ok' => true, 'id' => $res->json('id'), 'error' => null];
        }

        $error = match ($res->status()) {
            401, 403 => 'SMSGate login rejected — check the username/password in TSA Management',
            503      => 'SMSGate queue full or phone offline',
            default  => 'SMSGate error ' . $res->status() . ($res->json('message') ? ': ' . $res->json('message') : ''),
        };

        return ['ok' => false, 'id' => null, 'error' => $error];
    }
}
